SELECT * WHERE {
  ?s brick:hasName ?n .
  FILTER(LCASE(?n) IN ("coolingtower02","hwump01"))
  ?s a brick:Equipment .
}

SELECT ?s ?n ?cls WHERE {
  ?s brick:hasName ?n .
  ?s a ?cls .
  FILTER(LCONTAINS(LCASE(STR(?s)), "coolingtower") || LCONTAINS(LCASE(STR(?s)), "hwpump"))
}

